//! # pathland-codegen
//!
//! The **Catalog-Driven DSL generator**. It reads the single source of truth at
//! `lib/ui/components.yaml`, asserts every component/property id against
//! `pathland_opcode::constants` (a hard error on mismatch — the consistency
//! safety net), and emits the checked-in SwiftUI-like DSL for each target
//! language (currently Java).
//!
//! ## Usage
//!
//! ```sh
//! cargo run -p pathland-codegen
//! ```
//!
//! The generator is deterministic: given the same catalog it writes identical
//! output, so the emitted files are safe to check in.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use pathland_opcode::{component_type, property_id, size};

// ---------------------------------------------------------------------------
// YAML model
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
struct Catalog {
    component_ids: BTreeMap<String, u16>,
    property_ids: BTreeMap<String, u16>,
    enums: BTreeMap<String, EnumDef>,
    components: BTreeMap<String, ComponentDef>,
    modifiers: Vec<ModifierDef>,
    compound_modifiers: BTreeMap<String, CompoundDef>,
}

#[derive(serde::Deserialize)]
struct EnumDef {
    property: String,
    values: BTreeMap<String, u8>,
}

#[derive(serde::Deserialize)]
struct ComponentDef {
    label: String,
    #[serde(default)]
    text_content: bool,
    #[serde(default)]
    constructor_props: Vec<ConstructorProp>,
}

#[derive(serde::Deserialize)]
struct ConstructorProp {
    property: String,
    #[serde(rename = "type")]
    ty: String,
    #[serde(default)]
    r#enum: Option<String>,
}

#[derive(serde::Deserialize)]
struct ModifierDef {
    property: String,
    #[serde(rename = "type")]
    ty: String,
    #[serde(default)]
    r#enum: Option<String>,
}

#[derive(serde::Deserialize)]
struct CompoundDef {
    properties: Vec<ModifierDef>,
}

// ---------------------------------------------------------------------------
// Assertions against pathland_opcode::constants
// ---------------------------------------------------------------------------

/// Assert that every id in the catalog matches the protocol constants.
/// Returns a list of assertion errors (empty on success).
fn assert_ids(catalog: &Catalog) -> Vec<String> {
    let mut errors = Vec::new();

    // Component ids.
    let mut expected_components: BTreeMap<String, u16> = BTreeMap::new();
    expected_components.insert("hstack".into(), component_type::HSTACK);
    expected_components.insert("vstack".into(), component_type::VSTACK);
    expected_components.insert("text".into(), component_type::TEXT);
    expected_components.insert("button".into(), component_type::BUTTON);
    expected_components.insert("image".into(), component_type::IMAGE);
    expected_components.insert("switch".into(), component_type::SWITCH);
    expected_components.insert("text_field".into(), component_type::TEXT_FIELD);
    expected_components.insert("spacer".into(), component_type::SPACER);
    expected_components.insert("scrollview".into(), component_type::SCROLLVIEW);
    expected_components.insert("list".into(), component_type::LIST);
    expected_components.insert("grid".into(), component_type::GRID);
    expected_components.insert("comment".into(), component_type::COMMENT);

    for (name, id) in &expected_components {
        match catalog.component_ids.get(name) {
            Some(catalog_id) if catalog_id == id => {}
            Some(catalog_id) => errors.push(format!(
                "component `{name}`: catalog id 0x{catalog_id:04x} != protocol id 0x{id:04x}"
            )),
            None => errors.push(format!("component `{name}` missing from catalog")),
        }
    }

    // Property ids.
    let mut expected_props: BTreeMap<String, u16> = BTreeMap::new();
    expected_props.insert("spacing".into(), property_id::SPACING);
    expected_props.insert("alignment".into(), property_id::ALIGNMENT);
    expected_props.insert("justification".into(), property_id::JUSTIFICATION);
    expected_props.insert("padding".into(), property_id::PADDING);
    expected_props.insert("content_margins".into(), property_id::CONTENT_MARGINS);
    expected_props.insert("text".into(), property_id::TEXT);
    expected_props.insert("line_limit".into(), property_id::LINE_LIMIT);
    expected_props.insert("text_alignment".into(), property_id::TEXT_ALIGNMENT);
    expected_props.insert("truncation_mode".into(), property_id::TRUNCATION_MODE);
    expected_props.insert("background_color".into(), property_id::BACKGROUND_COLOR);
    expected_props.insert("border_width".into(), property_id::BORDER_WIDTH);
    expected_props.insert("border_color".into(), property_id::BORDER_COLOR);
    expected_props.insert("border_radius".into(), property_id::BORDER_RADIUS);
    expected_props.insert("padding_style".into(), property_id::PADDING_STYLE);
    expected_props.insert("font_size".into(), property_id::FONT_SIZE);
    expected_props.insert("font_weight".into(), property_id::FONT_WEIGHT);
    expected_props.insert("font_family".into(), property_id::FONT_FAMILY);
    expected_props.insert("color".into(), property_id::COLOR);
    expected_props.insert("width".into(), property_id::WIDTH);
    expected_props.insert("height".into(), property_id::HEIGHT);
    expected_props.insert("opacity".into(), property_id::OPACITY);
    expected_props.insert("visible".into(), property_id::VISIBLE);
    expected_props.insert("z_index".into(), property_id::Z_INDEX);
    expected_props.insert("clips_to_bounds".into(), property_id::CLIPS_TO_BOUNDS);
    expected_props.insert("padding_top".into(), property_id::PADDING_TOP);
    expected_props.insert("padding_right".into(), property_id::PADDING_RIGHT);
    expected_props.insert("padding_bottom".into(), property_id::PADDING_BOTTOM);
    expected_props.insert("padding_left".into(), property_id::PADDING_LEFT);
    expected_props.insert("role".into(), property_id::ROLE);
    expected_props.insert("state".into(), property_id::STATE);
    expected_props.insert("enabled".into(), property_id::ENABLED);
    expected_props.insert("selected".into(), property_id::SELECTED);

    for (name, id) in &expected_props {
        match catalog.property_ids.get(name) {
            Some(catalog_id) if catalog_id == id => {}
            Some(catalog_id) => errors.push(format!(
                "property `{name}`: catalog id 0x{catalog_id:04x} != protocol id 0x{id:04x}"
            )),
            None => errors.push(format!("property `{name}` missing from catalog")),
        }
    }

    // Every enum must reference a known property id and every enum value must
    // be within the u8 range (they are by construction).
    for (enum_name, def) in &catalog.enums {
        if !catalog.property_ids.contains_key(&def.property) {
            errors.push(format!("enum `{enum_name}` references unknown property `{}`", def.property));
        }
        if def.values.is_empty() {
            errors.push(format!("enum `{enum_name}` has no values"));
        }
    }

    errors
}

// ---------------------------------------------------------------------------
// Java emission
// ---------------------------------------------------------------------------

/// The directory where generated Java is written.
fn java_dir(repo_root: &Path) -> PathBuf {
    repo_root
        .join("lib/java/pathland-demo/src/main/java/pathland")
}

fn java_type_for(ty: &str, enum_name: Option<&str>) -> String {
    match ty {
        "f32" | "size" => "float".into(),
        "u32" => "int".into(),
        "bool" => "boolean".into(),
        "color" => "int".into(),
        "string" => "String".into(),
        "enum" => enum_name.unwrap_or("int").to_string(),
        other => panic!("unknown DSL type `{other}`"),
    }
}

fn write_java(path: &Path, content: &str) {
    std::fs::create_dir_all(path.parent().unwrap()).expect("create java dir");
    std::fs::write(path, content).expect("write java file");
}

fn java_literal_id(id: u16) -> String {
    format!("0x{id:04X}")
}

fn emit_constants(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml\n");
    out.push_str("package pathland;\n\n");
    out.push_str("/** Protocol ids and size sentinels (mirrors pathland_opcode::constants). */\n");
    out.push_str("public final class Constants {\n");
    out.push_str("    private Constants() {}\n\n");

    out.push_str("    // --- size sentinels (WIDTH / HEIGHT) ---\n");
    out.push_str(&format!("    public static final float FILL = {}f;\n", size::FILL));
    out.push_str(&format!("    public static final float HUG_CONTENT = {}f;\n", size::HUG_CONTENT));

    out.push_str("\n    // --- component ids ---\n");
    for (name, id) in &catalog.component_ids {
        out.push_str(&format!(
            "    public static final int {} = {};\n",
            name.to_ascii_uppercase(),
            java_literal_id(*id)
        ));
    }

    out.push_str("\n    // --- property ids ---\n");
    for (name, id) in &catalog.property_ids {
        out.push_str(&format!(
            "    public static final int {} = {};\n",
            name.to_ascii_uppercase(),
            java_literal_id(*id)
        ));
    }

    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Constants.java"), &out);
}

fn emit_enum(name: &str, def: &EnumDef, catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str(&format!("// Source of truth: lib/ui/components.yaml (enum `{name}`)\n"));
    out.push_str("package pathland;\n\n");
    out.push_str(&format!(
        "/** Typed `{name}` values. Wire value is the protocol ENUM value; see `{}` (0x{:04X}). */\n",
        def.property,
        catalog.property_ids.get(&def.property).copied().unwrap_or(0)
    ));
    out.push_str(&format!("public enum {name} {{\n"));
    for (value_name, value) in &def.values {
        out.push_str(&format!(
            "    {}({}),\n",
            value_name.to_ascii_uppercase(),
            value
        ));
    }
    out.push_str("\n    public final int wire;\n");
    out.push_str("    public final int property;\n");
    out.push_str("\n    public int wire() { return wire; }\n");
    out.push_str("\n    {name}(int wire) { this.wire = wire; this.property = Constants.{}; }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join(format!("{name}.java")), &out);
}

fn emit_component_node(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml\n");
    out.push_str("package pathland;\n\n");
    out.push_str("import java.util.ArrayList;\n");
    out.push_str("import java.util.List;\n\n");
    out.push_str("/** A component node (mirrors a DSL component). Constructor props are set on build. */\n");
    out.push_str("public final class ComponentNode implements View {\n");
    out.push_str("    private final int componentId;\n");
    out.push_str("    private final String text;\n");
    out.push_str("    private final List<View> children = new ArrayList<>();\n");
    out.push_str("    private final java.util.Map<Integer, Float> constructorProps = new java.util.LinkedHashMap<>();\n");
    out.push_str("\n");
    out.push_str("    public ComponentNode(int componentId, String text, List<View> children) {\n");
    out.push_str("        this.componentId = componentId;\n");
    out.push_str("        this.text = text;\n");
    out.push_str("        this.children.addAll(children);\n");
    out.push_str("    }\n");
    out.push_str("\n");
    out.push_str("    public ComponentNode setConstructorProp(int property, float value) {\n");
    out.push_str("        constructorProps.put(property, value);\n");
    out.push_str("        return this;\n");
    out.push_str("    }\n");
    out.push_str("\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = new Node(0, componentId);\n");
    out.push_str("        if (text != null) node.string = text;\n");
    out.push_str("        node.properties.putAll(constructorProps);\n");
    out.push_str("        for (View child : children) node.children.add(child.build());\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("ComponentNode.java"), &out);
}

fn emit_view(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml\n");
    out.push_str("package pathland;\n\n");
    out.push_str("/**\n");
    out.push_str(" * A composable view. Implementations build a {@link Node} subtree.\n");
    out.push_str(" *\n");
    out.push_str(" * Global modifiers are chainable on any view. The compound `frame` modifier\n");
    out.push_str(" * sizes a view (FILL/HUG_CONTENT sentinels) and optionally aligns it.\n");
    out.push_str(" */\n");
    out.push_str("public interface View {\n");
    out.push_str("    Node build();\n\n");

    // Simple (single-property) modifiers.
    for m in &catalog.modifiers {
        let method = m.property;
        let jt = java_type_for(&m.ty, m.r#enum.as_deref());
        let arg = if m.ty == "color" {
            "rgba"
        } else {
            "value"
        };
        let value_expr = match m.ty.as_str() {
            "color" => arg.to_string(),
            "bool" => format!("{} ? 1f : 0f", arg),
            "string" => {
                out.push_str(&format!(
                    "    default View {method}(String {arg}) {{\n        return new Modified(this, Constants.{}, new float[1]);\n    }}\n\n",
                    m.property.to_ascii_uppercase()
                ));
                continue;
            }
            "enum" => format!("{}().wire", arg),
            _ => arg.to_string(),
        };
        if m.ty != "string" {
            out.push_str(&format!(
                "    default View {method}({jt} {arg}) {{\n        return new Modified(this, Constants.{}, {value_expr});\n    }}\n\n",
                m.property.to_ascii_uppercase()
            ));
        }
    }

    // Compound `frame` modifier.
    out.push_str("    /**\n");
    out.push_str("     * Compound sizing modifier. Pass {@link Constants#FILL} / {@link Constants#HUG_CONTENT}\n");
    out.push_str("     * for a fixed axis, or {@code Float.NaN} to leave it to the native renderer.\n");
    out.push_str("     *\n");
    out.push_str("     * @param width     width hint (FILL / HUG_CONTENT / NaN for unset)\n");
    out.push_str("     * @param height    height hint (FILL / HUG_CONTENT / NaN for unset)\n");
    out.push_str("     * @param alignment cross-axis alignment, or null for unset\n");
    out.push_str("     */\n");
    out.push_str("    default View frame(float width, float height, Align alignment) {\n");
    out.push_str("        return new Frame(this, width, height, alignment);\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("View.java"), &out);
}

fn emit_dsl(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml\n");
    out.push_str("package pathland;\n\n");
    out.push_str("import java.util.Arrays;\n");
    out.push_str("import java.util.List;\n\n");
    out.push_str("/**\n");
    out.push_str(" * Static DSL entry points. Component CONSTRUCTOR properties are passed as\n");
    out.push_str(" * constructor args (never chainable); global modifiers chain on any view.\n");
    out.push_str(" */\n");
    out.push_str("public final class DSL {\n");
    out.push_str("    private DSL() {}\n\n");

    for (name, comp) in &catalog.components {
        let child_type = if is_container(name) { "View..." } else { "View..." };
        let _ = child_type;
        // Build the full constructor-property signature list.
        let has_props = !comp.constructor_props.is_empty();
        let has_text = comp.text_content;

        // 1) Default factory (children only, or content only for text).
        let default_args: String = if has_text {
            "String content".into()
        } else {
            "View... children".into()
        };
        let default_doc = if has_text {
            format!("Create a {label} with the given text content.", label = comp.label)
        } else {
            format!("Create a {label} with the given children.", label = comp.label)
        };
        out.push_str(&format!("    /** {default_doc} */\n"));
        out.push_str(&format!(
            "    public static View {name}({default_args}) {{\n"
        ));
        let ctor_args = if has_text {
            format!("Constants.{}, content, java.util.Collections.emptyList()", name.to_ascii_uppercase())
        } else {
            format!("Constants.{}, null, Arrays.asList(children)", name.to_ascii_uppercase())
        };
        out.push_str(&format!(
            "        return buildComponent(Constants.{}, {ctor_args});\n",
            name.to_ascii_uppercase()
        ));
        out.push_str("    }\n\n");

        // 2) Constructor-properties overload (only if the component has any).
        if has_props {
            let mut params = Vec::new();
            let mut setter_calls = Vec::new();
            for (i, prop) in comp.constructor_props.iter().enumerate() {
                let jt = java_type_for(&prop.ty, prop.r#enum.as_deref());
                let pname = prop.property;
                params.push(format!("{jt} {}", short_name(&pname, i)));
                setter_calls.push(format!(
                    "        node.setConstructorProp(Constants.{}, {});",
                    pname.to_ascii_uppercase(),
                    prop_expr(&prop, i)
                ));
            }
            let base_args: String = if has_text {
                "String content".into()
            } else {
                "View... children".into()
            };
            params.push(base_args);
            out.push_str(&format!(
                "    /** Create a {label} with constructor properties (structural/layout — never chainable). */\n",
                label = comp.label
            ));
            out.push_str(&format!(
                "    public static View {name}({}) {{\n",
                params.join(", ")
            ));
            out.push_str(&format!(
                "        ComponentNode node = new ComponentNode(Constants.{}, {}, {});\n",
                name.to_ascii_uppercase(),
                if has_text { "content" } else { "null" },
                if has_text {
                    "java.util.Collections.emptyList()"
                } else {
                    "Arrays.asList(children)"
                }
            ));
            for call in setter_calls {
                out.push_str(&call);
                out.push_str("\n");
            }
            out.push_str("        return node;\n");
            out.push_str("    }\n\n");
        }
    }

    out.push_str("    /** Build a component node. */\n");
    out.push_str("    private static View buildComponent(int componentId, String text, List<View> children) {\n");
    out.push_str("        return new ComponentNode(componentId, text, children);\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("DSL.java"), &out);
}

fn is_container(name: &str) -> bool {
    matches!(name, "hstack" | "vstack" | "scrollview" | "list" | "grid")
}

fn short_name(prop: &str, i: usize) -> String {
    // Use a short parameter name derived from the property; guaranteed unique
    // per overload because it is prefixed by its index when needed.
    let base = prop.replace('_', "");
    if i == 0 {
        base
    } else {
        format!("{base}{i}")
    }
}

fn prop_expr(prop: &ConstructorProp, i: usize) -> String {
    let pname = short_name(&prop.property, i);
    match prop.ty.as_str() {
        "enum" => format!("{}().wire", pname),
        "bool" => format!("{} ? 1f : 0f", pname),
        "u32" => format!("{}f", pname),
        _ => pname.to_string(),
    }
}

fn emit_modified(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml\n");
    out.push_str("package pathland;\n\n");
    out.push_str("/** A view wrapped by a single property modifier (innermost-first). */\n");
    out.push_str("final class Modified implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final int propertyId;\n");
    out.push_str("    private final float value;\n");
    out.push_str("\n");
    out.push_str("    Modified(View inner, int propertyId, float value) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.propertyId = propertyId;\n");
    out.push_str("        this.value = value;\n");
    out.push_str("    }\n");
    out.push_str("\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        node.properties.put(propertyId, value);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Modified.java"), &out);
}

fn emit_frame(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str("// GENERATED by pathland-codegen — DO NOT EDIT.\n");
    out.push_str("// Source of truth: lib/ui/components.yaml (compound modifier `frame`)\n");
    out.push_str("package pathland;\n\n");
    out.push_str("/** The compound `frame` modifier: width/height hints + optional alignment. */\n");
    out.push_str("final class Frame implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final float width;\n");
    out.push_str("    private final float height;\n");
    out.push_str("    private final Align alignment;\n");
    out.push_str("\n");
    out.push_str("    Frame(View inner, float width, float height, Align alignment) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.width = width;\n");
    out.push_str("        this.height = height;\n");
    out.push_str("        this.alignment = alignment;\n");
    out.push_str("    }\n");
    out.push_str("\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        if (!Float.isNaN(width)) node.properties.put(Constants.WIDTH, width);\n");
    out.push_str("        if (!Float.isNaN(height)) node.properties.put(Constants.HEIGHT, height);\n");
    out.push_str("        if (alignment != null) node.properties.put(Constants.ALIGNMENT, (float) alignment.wire);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Frame.java"), &out);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

fn main() {
    let repo_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("resolve repo root (crates/pathland-codegen -> lib/rust -> lib -> repo)");

    let catalog_path = repo_root.join("lib/ui/components.yaml");
    let catalog_text = std::fs::read_to_string(&catalog_path)
        .unwrap_or_else(|e| panic!("read {}: {e}", catalog_path.display()));
    let catalog: Catalog =
        serde_yaml::from_str(&catalog_text).expect("parse lib/ui/components.yaml");

    // Assertions (hard errors on drift).
    let errors = assert_ids(&catalog);
    if !errors.is_empty() {
        eprintln!("pathland-codegen: catalog/constants mismatch:");
        for e in &errors {
            eprintln!("  - {e}");
        }
        std::process::exit(1);
    }

    // Emit Java DSL.
    emit_constants(&catalog, &repo_root);
    for (name, def) in &catalog.enums {
        emit_enum(name, def, &catalog, &repo_root);
    }
    emit_component_node(&catalog, &repo_root);
    emit_view(&catalog, &repo_root);
    emit_dsl(&catalog, &repo_root);
    emit_modified(&catalog, &repo_root);
    emit_frame(&catalog, &repo_root);

    println!(
        "pathland-codegen: OK — {} components, {} properties, {} enums asserted against constants; Java DSL emitted.",
        catalog.components.len(),
        catalog.property_ids.len(),
        catalog.enums.len()
    );
}

//! # pathland-codegen
//!
//! The **Catalog-Driven DSL generator**. It reads the single source of truth at
//! `lib/ui/components.yaml`, asserts every component/property id against
//! `pathland_opcode::constants` (a hard error on mismatch — the consistency
//! safety net), and emits the checked-in SwiftUI-like DSL for each target
//! language (currently Java).
//!
//! ## Usage
//!
//! ```sh
//! cargo run -p pathland-codegen
//! ```
//!
//! The generator is deterministic: given the same catalog it writes identical
//! output, so the emitted files are safe to check in.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use pathland_opcode::{component_type, property_id, size};

// ---------------------------------------------------------------------------
// YAML model
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
struct Catalog {
    component_ids: BTreeMap<String, u16>,
    property_ids: BTreeMap<String, u16>,
    enums: BTreeMap<String, EnumDef>,
    components: BTreeMap<String, ComponentDef>,
    modifiers: Vec<ModifierDef>,
    compound_modifiers: BTreeMap<String, CompoundDef>,
}

#[derive(serde::Deserialize)]
struct EnumDef {
    property: String,
    values: BTreeMap<String, u8>,
}

#[derive(serde::Deserialize)]
struct ComponentDef {
    label: String,
    #[serde(default)]
    text_content: bool,
    #[serde(default)]
    constructor_props: Vec<ConstructorProp>,
}

#[derive(serde::Deserialize)]
struct ConstructorProp {
    property: String,
    #[serde(rename = "type")]
    ty: String,
    #[serde(default)]
    r#enum: Option<String>,
}

#[derive(serde::Deserialize)]
struct ModifierDef {
    property: String,
    #[serde(rename = "type")]
    ty: String,
    #[serde(default)]
    r#enum: Option<String>,
}

#[derive(serde::Deserialize)]
struct CompoundDef {
    properties: Vec<ModifierDef>,
}

// ---------------------------------------------------------------------------
// Assertions against pathland_opcode::constants
// ---------------------------------------------------------------------------

fn assert_ids(catalog: &Catalog) -> Vec<String> {
    let mut errors = Vec::new();

    let expected_components: &[(&str, u16)] = &[
        ("hstack", component_type::HSTACK),
        ("vstack", component_type::VSTACK),
        ("text", component_type::TEXT),
        ("button", component_type::BUTTON),
        ("image", component_type::IMAGE),
        ("switch", component_type::SWITCH),
        ("text_field", component_type::TEXT_FIELD),
        ("spacer", component_type::SPACER),
        ("scrollview", component_type::SCROLLVIEW),
        ("list", component_type::LIST),
        ("grid", component_type::GRID),
        ("comment", component_type::COMMENT),
    ];
    for (name, id) in expected_components {
        match catalog.component_ids.get(*name) {
            Some(cid) if cid == id => {}
            Some(cid) => errors.push(format!(
                "component `{name}`: catalog 0x{cid:04x} != protocol 0x{id:04x}"
            )),
            None => errors.push(format!("component `{name}` missing from catalog")),
        }
    }

    let expected_props: &[(&str, u16)] = &[
        ("spacing", property_id::SPACING),
        ("alignment", property_id::ALIGNMENT),
        ("justification", property_id::JUSTIFICATION),
        ("padding", property_id::PADDING),
        ("content_margins", property_id::CONTENT_MARGINS),
        ("text", property_id::TEXT),
        ("line_limit", property_id::LINE_LIMIT),
        ("text_alignment", property_id::TEXT_ALIGNMENT),
        ("truncation_mode", property_id::TRUNCATION_MODE),
        ("background_color", property_id::BACKGROUND_COLOR),
        ("border_width", property_id::BORDER_WIDTH),
        ("border_color", property_id::BORDER_COLOR),
        ("border_radius", property_id::BORDER_RADIUS),
        ("padding_style", property_id::PADDING_STYLE),
        ("font_size", property_id::FONT_SIZE),
        ("font_weight", property_id::FONT_WEIGHT),
        ("font_family", property_id::FONT_FAMILY),
        ("color", property_id::COLOR),
        ("width", property_id::WIDTH),
        ("height", property_id::HEIGHT),
        ("opacity", property_id::OPACITY),
        ("visible", property_id::VISIBLE),
        ("z_index", property_id::Z_INDEX),
        ("clips_to_bounds", property_id::CLIPS_TO_BOUNDS),
        ("padding_top", property_id::PADDING_TOP),
        ("padding_right", property_id::PADDING_RIGHT),
        ("padding_bottom", property_id::PADDING_BOTTOM),
        ("padding_left", property_id::PADDING_LEFT),
        ("role", property_id::ROLE),
        ("state", property_id::STATE),
        ("enabled", property_id::ENABLED),
        ("selected", property_id::SELECTED),
    ];
    for (name, id) in expected_props {
        match catalog.property_ids.get(*name) {
            Some(pid) if pid == id => {}
            Some(pid) => errors.push(format!(
                "property `{name}`: catalog 0x{pid:04x} != protocol 0x{id:04x}"
            )),
            None => errors.push(format!("property `{name}` missing from catalog")),
        }
    }

    for (enum_name, def) in &catalog.enums {
        if !catalog.property_ids.contains_key(&def.property) {
            errors.push(format!(
                "enum `{enum_name}` references unknown property `{}`",
                def.property
            ));
        }
        if def.values.is_empty() {
            errors.push(format!("enum `{enum_name}` has no values"));
        }
    }

    errors
}

// ---------------------------------------------------------------------------
// Java emission helpers
// ---------------------------------------------------------------------------

fn java_dir(repo_root: &Path) -> PathBuf {
    repo_root.join("lib/java/pathland-demo/src/main/java/pathland")
}

fn write_java(path: &Path, content: &str) {
    std::fs::create_dir_all(path.parent().unwrap()).expect("create java dir");
    std::fs::write(path, content).expect("write java file");
}

fn header(file: &str) -> String {
    format!(
        "// GENERATED by pathland-codegen — DO NOT EDIT.\n// Source of truth: lib/ui/components.yaml ({file})\n"
    )
}

// ---------------------------------------------------------------------------
// Emitters
// ---------------------------------------------------------------------------

fn emit_constants(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("Constants"));
    out.push_str("package pathland;\n\n");
    out.push_str("/** Protocol ids and size sentinels (mirrors pathland_opcode::constants). */\n");
    out.push_str("public final class Constants {\n");
    out.push_str("    private Constants() {}\n\n");

    out.push_str("    // --- size sentinels (WIDTH / HEIGHT) ---\n");
    out.push_str(&format!("    public static final float FILL = {}f;\n", size::FILL));
    out.push_str(&format!(
        "    public static final float HUG_CONTENT = {}f;\n",
        size::HUG_CONTENT
    ));

    out.push_str("\n    // --- component ids ---\n");
    for (name, id) in &catalog.component_ids {
        out.push_str(&format!(
            "    public static final int {} = 0x{:04X};\n",
            name.to_ascii_uppercase(),
            id
        ));
    }

    out.push_str("\n    // --- property ids ---\n");
    for (name, id) in &catalog.property_ids {
        out.push_str(&format!(
            "    public static final int {} = 0x{:04X};\n",
            name.to_ascii_uppercase(),
            id
        ));
    }

    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Constants.java"), &out);
}

fn emit_enum(name: &str, def: &EnumDef, catalog: &Catalog, repo_root: &Path) {
    let prop_id = catalog.property_ids.get(&def.property).copied().unwrap_or(0);
    let mut out = String::new();
    out.push_str(&header(&format!("enum `{name}`")));
    out.push_str("package pathland;\n\n");
    out.push_str(&format!(
        "/** Typed `{name}` values. Wire value is the protocol ENUM value; property `{}` = 0x{:04X}. */\n",
        def.property, prop_id
    ));
    out.push_str(&format!("public enum {name} {{\n"));
    for (value_name, value) in &def.values {
        out.push_str(&format!(
            "    {}({}),\n",
            value_name.to_ascii_uppercase(),
            value
        ));
    }
    out.push_str("\n    public final int wire;\n");
    out.push_str(&format!(
        "    public final int property = Constants.{};\n",
        def.property.to_ascii_uppercase()
    ));
    out.push_str("\n    public int wire() { return wire; }\n");
    out.push_str(&format!(
        "\n    {name}(int wire) {{ this.wire = wire; }}\n"
    ));
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join(format!("{name}.java")), &out);
}

fn emit_component_node(repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("ComponentNode"));
    out.push_str("package pathland;\n\n");
    out.push_str("import java.util.ArrayList;\n");
    out.push_str("import java.util.List;\n\n");
    out.push_str("/** A component node (mirrors a DSL component). Constructor props are set on build. */\n");
    out.push_str("public final class ComponentNode implements View {\n");
    out.push_str("    private final int componentId;\n");
    out.push_str("    private final String text;\n");
    out.push_str("    private final List<View> children = new ArrayList<>();\n");
    out.push_str("    private final java.util.Map<Integer, Float> constructorProps = new java.util.LinkedHashMap<>();\n\n");
    out.push_str("    public ComponentNode(int componentId, String text, List<View> children) {\n");
    out.push_str("        this.componentId = componentId;\n");
    out.push_str("        this.text = text;\n");
    out.push_str("        this.children.addAll(children);\n");
    out.push_str("    }\n\n");
    out.push_str("    public ComponentNode setConstructorProp(int property, float value) {\n");
    out.push_str("        constructorProps.put(property, value);\n");
    out.push_str("        return this;\n");
    out.push_str("    }\n\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = new Node(0, componentId);\n");
    out.push_str("        if (text != null) node.string = text;\n");
    out.push_str("        node.properties.putAll(constructorProps);\n");
    out.push_str("        for (View child : children) node.children.add(child.build());\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("ComponentNode.java"), &out);
}

fn emit_view(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("View"));
    out.push_str("package pathland;\n\n");
    out.push_str("/**\n");
    out.push_str(" * A composable view. Implementations build a {@link Node} subtree.\n");
    out.push_str(" *\n");
    out.push_str(" * Global modifiers are chainable on any view. The compound `frame` modifier\n");
    out.push_str(" * sizes a view (FILL/HUG_CONTENT sentinels) and optionally aligns it.\n");
    out.push_str(" */\n");
    out.push_str("public interface View {\n");
    out.push_str("    Node build();\n\n");

    for m in &catalog.modifiers {
        let method = m.property;
        let arg = "value";
        let jt = match m.ty.as_str() {
            "string" => "String",
            "bool" => "boolean",
            "enum" => m.r#enum.as_deref().unwrap_or("int"),
            _ => "float",
        };
        let value_expr = match m.ty.as_str() {
            "color" => arg.to_string(),
            "bool" => format!("{arg} ? 1f : 0f"),
            "string" => "value.hashCode()".to_string(), // placeholder, see below
            "enum" => format!("{arg}.wire"),
            _ => arg.to_string(),
        };
        out.push_str(&format!(
            "    default View {method}({jt} {arg}) {{\n"
        ));
        if m.ty == "string" {
            // String-valued properties (font_family) are stored in Node.string
            // via a dedicated modifier path; emit a helper that records the
            // string so the bridge can apply it.
            out.push_str(&format!(
                "        return new StringProp(this, Constants.{}, {arg});\n",
                m.property.to_ascii_uppercase()
            ));
        } else {
            out.push_str(&format!(
                "        return new Modified(this, Constants.{}, {value_expr});\n",
                m.property.to_ascii_uppercase()
            ));
        }
        out.push_str("    }\n\n");
    }

    out.push_str("    /**\n");
    out.push_str("     * Compound sizing modifier. Pass {@link Constants#FILL} / {@link Constants#HUG_CONTENT}\n");
    out.push_str("     * for a fixed axis, or {@code Float.NaN} to leave it to the native renderer.\n");
    out.push_str("     *\n");
    out.push_str("     * @param width     width hint (FILL / HUG_CONTENT / NaN for unset)\n");
    out.push_str("     * @param height    height hint (FILL / HUG_CONTENT / NaN for unset)\n");
    out.push_str("     * @param alignment cross-axis alignment, or null for unset\n");
    out.push_str("     */\n");
    out.push_str("    default View frame(float width, float height, Align alignment) {\n");
    out.push_str("        return new Frame(this, width, height, alignment);\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("View.java"), &out);
}

fn is_container(name: &str) -> bool {
    matches!(name, "hstack" | "vstack" | "scrollview" | "list" | "grid")
}

fn emit_dsl(catalog: &Catalog, repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("DSL"));
    out.push_str("package pathland;\n\n");
    out.push_str("import java.util.Arrays;\n");
    out.push_str("import java.util.List;\n\n");
    out.push_str("/**\n");
    out.push_str(" * Static DSL entry points. Component CONSTRUCTOR properties are passed as\n");
    out.push_str(" * constructor args (never chainable); global modifiers chain on any view.\n");
    out.push_str(" */\n");
    out.push_str("public final class DSL {\n");
    out.push_str("    private DSL() {}\n\n");

    for (name, comp) in &catalog.components {
        let comp_const = format!("Constants.{}", name.to_ascii_uppercase());
        let has_text = comp.text_content;

        // 1) Default factory.
        let default_doc = if has_text {
            format!("Create a {} with the given text content.", comp.label)
        } else {
            format!("Create a {} with the given children.", comp.label)
        };
        out.push_str(&format!("    /** {default_doc} */\n"));
        if has_text {
            out.push_str(&format!(
                "    public static View {name}(String content) {{\n"
            ));
            out.push_str(&format!(
                "        return new ComponentNode({comp_const}, content, java.util.Collections.emptyList());\n"
            ));
        } else {
            out.push_str(&format!("    public static View {name}(View... children) {{\n"));
            out.push_str(&format!(
                "        return new ComponentNode({comp_const}, null, Arrays.asList(children));\n"
            ));
        }
        out.push_str("    }\n\n");

        // 2) Constructor-properties overload (only if the component has any).
        if !comp.constructor_props.is_empty() {
            let mut params = Vec::new();
            let mut setter_calls = Vec::new();
            for (i, prop) in comp.constructor_props.iter().enumerate() {
                let jt = match prop.ty.as_str() {
                    "enum" => prop.r#enum.as_deref().unwrap_or("int").to_string(),
                    "u32" => "int".to_string(),
                    "bool" => "boolean".to_string(),
                    _ => "float".to_string(),
                };
                let pname = short_name(&prop.property, i);
                params.push(format!("{jt} {pname}"));
                let wire_expr = match prop.ty.as_str() {
                    "enum" => format!("{pname}.wire"),
                    "bool" => format!("{pname} ? 1f : 0f"),
                    "u32" => format!("(float) {pname}"),
                    _ => pname.clone(),
                };
                setter_calls.push(format!(
                    "        node.setConstructorProp(Constants.{}, {});\n",
                    prop.property.to_ascii_uppercase(),
                    wire_expr
                ));
            }
            params.push(if has_text {
                "String content".to_string()
            } else {
                "View... children".to_string()
            });

            out.push_str(&format!(
                "    /** Create a {} with constructor properties (structural/layout — never chainable). */\n",
                comp.label
            ));
            out.push_str(&format!(
                "    public static View {name}({}) {{\n",
                params.join(", ")
            ));
            let node_ctor = if has_text {
                format!(
                    "new ComponentNode({comp_const}, content, java.util.Collections.emptyList())"
                )
            } else {
                format!("new ComponentNode({comp_const}, null, Arrays.asList(children))")
            };
            out.push_str(&format!("        ComponentNode node = {node_ctor};\n"));
            for call in setter_calls {
                out.push_str(&call);
            }
            out.push_str("        return node;\n");
            out.push_str("    }\n\n");
        }
    }

    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("DSL.java"), &out);
}

fn short_name(prop: &str, i: usize) -> String {
    let base = prop.replace('_', "");
    if i == 0 {
        base
    } else {
        format!("{base}{i}")
    }
}

fn emit_modified(repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("Modified"));
    out.push_str("package pathland;\n\n");
    out.push_str("/** A view wrapped by a single float property modifier (innermost-first). */\n");
    out.push_str("final class Modified implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final int propertyId;\n");
    out.push_str("    private final float value;\n\n");
    out.push_str("    Modified(View inner, int propertyId, float value) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.propertyId = propertyId;\n");
    out.push_str("        this.value = value;\n");
    out.push_str("    }\n\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        node.properties.put(propertyId, value);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Modified.java"), &out);
}

fn emit_string_prop(repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("StringProp"));
    out.push_str("package pathland;\n\n");
    out.push_str("/** A view wrapped by a string-valued property modifier (e.g. font_family). */\n");
    out.push_str("final class StringProp implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final int propertyId;\n");
    out.push_str("    private final String value;\n\n");
    out.push_str("    StringProp(View inner, int propertyId, String value) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.propertyId = propertyId;\n");
    out.push_str("        this.value = value;\n");
    out.push_str("    }\n\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        node.stringProps.put(propertyId, value);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("StringProp.java"), &out);
}

fn emit_frame(repo_root: &Path) {
    let mut out = String::new();
    out.push_str(&header("Frame"));
    out.push_str("package pathland;\n\n");
    out.push_str("/** The compound `frame` modifier: width/height hints + optional alignment. */\n");
    out.push_str("final class Frame implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final float width;\n");
    out.push_str("    private final float height;\n");
    out.push_str("    private final Align alignment;\n\n");
    out.push_str("    Frame(View inner, float width, float height, Align alignment) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.width = width;\n");
    out.push_str("        this.height = height;\n");
    out.push_str("        this.alignment = alignment;\n");
    out.push_str("    }\n\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        if (!Float.isNaN(width)) node.properties.put(Constants.WIDTH, width);\n");
    out.push_str("        if (!Float.isNaN(height)) node.properties.put(Constants.HEIGHT, height);\n");
    out.push_str("        if (alignment != null) node.properties.put(Constants.ALIGNMENT, (float) alignment.wire);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Frame.java"), &out);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

fn main() {
    let repo_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("resolve repo root");

    let catalog_path = repo_root.join("lib/ui/components.yaml");
    let catalog_text = std::fs::read_to_string(&catalog_path)
        .unwrap_or_else(|e| panic!("read {}: {e}", catalog_path.display()));
    let catalog: Catalog =
        serde_yaml::from_str(&catalog_text).expect("parse lib/ui/components.yaml");

    let errors = assert_ids(&catalog);
    if !errors.is_empty() {
        eprintln!("pathland-codegen: catalog/constants mismatch:");
        for e in &errors {
            eprintln!("  - {e}");
        }
        std::process::exit(1);
    }

    emit_constants(&catalog, &repo_root);
    for (name, def) in &catalog.enums {
        emit_enum(name, def, &catalog, &repo_root);
    }
    emit_component_node(&repo_root);
    emit_view(&catalog, &repo_root);
    emit_dsl(&catalog, &repo_root);
    emit_modified(&repo_root);
    emit_string_prop(&repo_root);
    emit_frame(&repo_root);

    println!(
        "pathland-codegen: OK — {} components, {} properties, {} enums asserted against constants; Java DSL emitted.",
        catalog.components.len(),
        catalog.property_ids.len(),
        catalog.enums.len()
    );
}

