    out.push_str(&header("Frame"));
    out.push_str("package pathland;\n\n");
    out.push_str("/** The compound `frame` modifier: width/height hints + optional alignment. */\n");
    out.push_str("final class Frame implements View {\n");
    out.push_str("    private final View inner;\n");
    out.push_str("    private final float width;\n");
    out.push_str("    private final float height;\n");
    out.push_str("    private final Align alignment;\n\n");
    out.push_str("    Frame(View inner, float width, float height, Align alignment) {\n");
    out.push_str("        this.inner = inner;\n");
    out.push_str("        this.width = width;\n");
    out.push_str("        this.height = height;\n");
    out.push_str("        this.alignment = alignment;\n");
    out.push_str("    }\n\n");
    out.push_str("    @Override\n");
    out.push_str("    public Node build() {\n");
    out.push_str("        Node node = inner.build();\n");
    out.push_str("        if (!Float.isNaN(width)) node.properties.put(Constants.WIDTH, width);\n");
    out.push_str("        if (!Float.isNaN(height)) node.properties.put(Constants.HEIGHT, height);\n");
    out.push_str("        if (alignment != null) node.properties.put(Constants.ALIGNMENT, (float) alignment.wire);\n");
    out.push_str("        return node;\n");
    out.push_str("    }\n");
    out.push_str("}\n");
    write_java(&java_dir(repo_root).join("Frame.java"), &out);
}

